import { readFileSync } from 'node:fs'

const raw = readFileSync('.flowgate/project-clarify.md', 'utf8')
const lines = raw.split(/\r?\n/)
const headings = []
lines.forEach((line, index) => {
  const match = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line)
  if (match) headings.push({ title: match[2], line: index })
})
console.log(JSON.stringify({ length: raw.length, first: raw.slice(0, 30), headings }, null, 2))

